export function clampNumber(x: number, lo: number, hi: number): number {
  if (x < lo) return lo;
  if (x > hi) return hi;
  return x;
}

export interface ClampArgs {
  value: number;
  min: number;
  max: number;
}

export function clamp(args: ClampArgs): number {
  const { value, min, max } = args;
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

export function clamp(x: number, lo: number, hi: number): [number, boolean] {
  if (x < lo) return [lo, true];
  if (x > hi) return [hi, true];
  return [x, false];
}
